// Generated: ONE realistic-ish HTML payload, compressed four ways, so a decoder benchmark
// compares like with like. All four must decode to exactly RAW_BYTES — the shared assertion in
// the bench relies on it, and it caught a zstd fixture built from a different payload.
const B64=(s)=>Uint8Array.from(atob(s),c=>c.charCodeAt(0));
export const RAW_BYTES = 262548;
export const BR = B64("");
export const BR11 = B64("");
export const GZ = B64("");
export const ZSTD = B64("");
